    MouHeading('5. CUSTOMER ORDERS'),
    MouParagraph('5.1 All customer orders relating to artworks covered by this MOU shall be processed exclusively through Galleryzone unless otherwise authorized in writing.'),
    MouParagraph('5.2 Galleryzone shall be responsible for customer invoicing, collection of customer payments, order processing, logistics coordination, customer order communications and applicable post-order processes.'),
