    MouHeading('9. INCENTIVE STRUCTURE AND SETTLEMENT'),
    MouParagraph('9.1 For every successful sale facilitated through the Aggregator, the Aggregator shall be entitled to twenty percent (20%) of the difference between the applicable Listed Selling Price and Artist Price, subject to this MOU.'),
    MouParagraph('9.2 Aggregator Incentive = 20% × (Listed Selling Price − Artist Price).'),
