    MouParagraph('9.6 Incentive becomes payable only after full customer payment, confirmed successful delivery, and completion of any applicable return/cancellation/cooling-off period.'),
    MouParagraph('9.7 Cancelled, refunded, reversed or otherwise unsuccessful transactions do not generate the corresponding incentive.'),
    MouParagraph('9.8 Final settlement remains subject to lawful deductions, adjustments, taxes, refunds, chargebacks, logistics charges and other amounts recoverable under this MOU.'),
    MouHeading('10. DELIVERY, PACKAGING AND LOGISTICS'),
    MouParagraph('10.1 Delivery shall ordinarily be arranged through Galleryzone’s authorized logistics partners.'),
    MouParagraph('10.2 Galleryzone shall coordinate shipment, applicable logistics, tracking where available, and customer delivery updates.'),
    MouParagraph('10.3 Unless otherwise specified, applicable shipping charges shall be borne by the customer.'),
