    MouParagraph('16.14 Delisting does not waive Galleryzone’s right to recover outstanding amounts, loss, damage, costs, liabilities or other remedies.'),
    MouHeading('17. GOVERNING LAW AND JURISDICTION'),
    MouParagraph('17.1 This MOU shall be governed by the laws of India.'),
    MouParagraph('17.2 Subject to the arbitration provisions, competent courts at Hyderabad, Telangana shall have jurisdiction over matters requiring judicial intervention, including interim relief, enforcement of arbitral awards and matters not legally capable of arbitration.'),
    MouHeading('18. DISPUTE RESOLUTION AND ARBITRATION'),
    MouParagraph('18.1 Parties shall first attempt in good faith to resolve disputes through written notice and discussions for thirty (30) days.'),
