    MouParagraph('20.6 This MOU may be executed in counterparts, including electronically, each deemed an original.'),
    MouHeading('21. PERSONAL DATA PROTECTION AND PRIVACY'),
    MouParagraph('21.1 Galleryzone may collect and process the Aggregator’s personal/business data, including identity, contact, address, tax, payment, verification, transaction, inventory, provenance and other information reasonably necessary for onboarding, KYC/verification, listing, sale, settlement, logistics, customer support, fraud prevention, legal compliance, record keeping and legitimate business purposes.'),
    MouParagraph('21.2 Galleryzone shall process such data in accordance with applicable data-protection and privacy laws, including the Digital Personal Data Protection Act, 2023 and applicable rules, as and when applicable.'),
    MouParagraph('21.3 Relevant information may be shared with authorized service providers, payment processors, logistics providers, insurers, Artists, professional advisers, auditors, regulators, tax authorities and other parties where reasonably necessary or legally required.'),
    MouParagraph('21.4 Galleryzone shall take reasonable technical and organizational measures appropriate to the nature of the data.'),
    MouParagraph('21.5 Data may be retained as reasonably necessary for contractual, tax, accounting, fraud-prevention, dispute-resolution, provenance, legal or regulatory requirements.'),
